    const call = orchestrator.processMessage(createSession('hello'));
    const error = await call.catch(e => e);

    expect({
      message: error instanceof Error ? error.message : String(error),
      caughtError,
      afterSessionRan,
    }).toEqual({
      message: 'Database connection failed in beforeSession',
      caughtError: errorToThrow,
      afterSessionRan: true,
    });
  });
});

parameters.old_string:
    const call = orchestrator.processMessage(createSession('hello'));
    await expect(call).rejects.toThrow('Database connection failed in beforeSession');

    // Ensure finally block has finished before asserting on its side effects.
    await call.catch(() => {});

    expect({caughtError, afterSessionRan}).toEqual({
      caughtError: errorToThrow,
      afterSessionRan: true,
    });
  });
});
